mapper.sql:
WHERE r.organization_id = #{organizationId}
AND r.status = #{status}

    AND (
        (r.booking_type = 'HOTEL' AND hb.hotel_id IN #{hid})
        OR (r.booking_type = 'ACTIVITY' AND ao.activity_booking_id IN #{pid})
    )

mapper.update:
UPDATE booking_change_requests SET status = #{status}, responded_by = #{respondedBy}, response_note = #{responseNote},
    responded_at = CASE WHEN #{status} IN ('ACCEPTED','DECLINED') THEN #{now} ELSE responded_at END,
    price_after = COALESCE(#{priceAfter}, price_after), updated_at = #{now}
WHERE id = #{id} AND status = #{fromStatus}
